curl -s -X PUT  http://127.0.0.1:38111/api/v1/fleet/cooldown \
     -H 'Content-Type: application/json' -d '{"cooldown_seconds":7200}'
curl -s GET  http://127.0.0.1:38111/api/v1/fleet/cooldown
# -> {"cooldown_seconds":7200,"source":"pin","legacy_43200_removed":true}
```

