Built a greenfield `internal/ai` package in `/home/kara` containing a deterministic LLM provider router plus a capability side-table. The pipeline runs in exactly the stated order — **cost filter → type filter → complexity escalation → priority tie-break → fallback chain → default** — and never mutates `ProviderConfig`, so existing `NewClient` callers are untouched.

**`internal/ai/router.go`** — the router, with each stage as an independently testable method:

```go
// Primary runs stages 1-4 and returns the ordered candidate pool.
func (r *Router) Primary(opts RouteOptions) []Provider {
	if opts.Complexity == 0 {
		opts.Complexity = ComplexityLow
	}
	pool := make([]Provider, 0, len(r.order))
	for _, p := range r.order {
		if _, ok := r.cap(p); ok { // side-table is the source of routing truth
			pool = append(pool, p)
		}
	}
	pool = r.costFilter(pool, opts.MaxCost)           // 1. cost ceiling
	pool = r.typeFilter(pool, opts.RequiredType)      // 2. model type
	pool = r.complexityEscalate(pool, opts.Complexity) // 3. tier escalation
	return r.priorityTieBreak(pool)                    // 4. deterministic sort
}

// priorityTieBreak: (Priority asc, CostPer1K asc, registration index) — the
// registration-index term makes even full ties deterministic.
func (r *Router) priorityTieBreak(providers []Provider) []Provider {
	out := append([]Provider(nil), providers...)
	sort.SliceStable(out, func(i, j int) bool {
		ci, _ := r.cap(out[i])
		cj, _ := r.cap(out[j])
		if ci.Priority != cj.Priority { return ci.Priority < cj.Priority }
		if ci.CostPer1K != cj.CostPer1K { return ci.CostPer1K < cj.CostPer1K }
		return r.idx[out[i]] < r.idx[out[j]]
	})
	return out
}

// Candidates: primary pool (1-4) -> fallback chain (5) -> default (6).
func (r *Router) Candidates(opts RouteOptions) []Provider { /* dedup chain + default */ }

// Route: head of Primary, else Default, else error.
func (r *Router) Route(opts RouteOptions) (Provider, error) { ... }

// RouteWithFallback: tries the full plan at call time; attempt returns nil on success.
func (r *Router) RouteWithFallback(opts RouteOptions, attempt func(Provider) error) (Provider, error) { ... }
```

**`internal/ai/capability.go`** — the side-table keyed by provider, deliberately separate from config:

