CREATE OR REPLACE FUNCTION staff_find_student_by_email(p_email TEXT)
RETURNS SETOF users
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
  SELECT u.*
  FROM users u
  WHERE u.email = lower(p_email)
    AND (u.school_id = auth.current_school_id() OR u.school_id IS NULL)  -- NULL branch added
