```go
const (
	rlimitMemlock = 8          // RLIMIT_MEMLOCK (linux, asm-generic/resource.h)
	rlimInfinity  = ^uint64(0) // RLIM_INFINITY
)

func memlockDegraded() bool {
	var lim syscall.Rlimit
	if err := syscall.Getrlimit(rlimitMemlock, &lim); err != nil {
		return false
	}
	if lim.Cur == rlimInfinity {
		return false
	}
	return lim.Cur < memlockHealthyBytes // 64 MiB budget
}
