```ts
import { readFileSync, writeFileSync, existsSync } from 'node:fs';
import { kill } from 'node:process';
import type { LockContents } from './types';
import { LOCK_STALE_MS } from './constants';

export function readLockFile(filePath: string): LockContents | null {
  if (!existsSync(filePath)) return null;
  try { return JSON.parse(readFileSync(filePath, 'utf8')) as LockContents; }
  catch { return null; } // corrupt / torn write -> treated as no lock
}

export function writeLockFile(filePath: string, contents: LockContents): boolean {
  try { writeFileSync(filePath, JSON.stringify(contents), { flag: 'wx' }); return true; }
  catch { return false; } // EEXIST -> lock held
}

export function isLockStale(createdAtMs: number, nowMs: number, maxAgeMs = LOCK_STALE_MS): boolean {
  return nowMs - createdAtMs >= maxAgeMs;
}

export function isProcessAlive(pid: number): boolean {
  if (!Number.isInteger(pid) || pid <= 0) return false;
  try { kill(pid, 0); return true; }
  catch (e) { return (e as NodeJS.ErrnoException).code === 'EPERM'; } // alive, no perms
}
```

