Two independent defects combine to make hash-only `/open` never accrue claimable credits.

**Defect 1 — `open.go:120-123` gates `RecordCredit` on body fields the spec doesn't send.** The documented spec `OpenPageRequest` carries only `hash`; `PublisherID`/`Domain` are never present, so the gate `if req.PublisherID != "" && req.Domain != ""` is always false and no credit row is ever created. Fix: drop the body gating and resolve `hash → URL → domain → publisher` from `content_hash_store` + `verified_domains`, then credit the resolved publisher.

```go
// open.go — spec-compliant request carries ONLY hash
type OpenPageRequest struct {
    Hash string `json:"hash" binding:"required"`
}

type OpenPageResponse struct {
    OK       bool   `json:"ok"`
    URL      string `json:"url,omitempty"`
    Credited bool   `json:"credited"`
}

func (s *Server) Open(c *gin.Context) {
    var req OpenPageRequest
    if err := c.ShouldBindJSON(&req); err != nil {
        c.JSON(http.StatusBadRequest, gin.H{"error": "hash required"})
        return
    }

    // 1. hash -> url (content_hash_store), case-insensitive
    url, err := s.contentHashes.URLByHash(strings.ToLower(req.Hash))
    if err != nil || url == "" {
        c.JSON(http.StatusNotFound, gin.H{"error": "unknown content hash"})
        return
    }

    // 2. url -> domain
    u, err := urlpkg.Parse(url)
    if err != nil || u.Host == "" {
        c.JSON(http.StatusUnprocessableEntity, gin.H{"error": "unresolvable url"})
        return
    }

    // 3. domain -> publisher (verified_domains)
    publisher, ok, err := s.verifiedDomains.PublisherByDomain(u.Host)
    if err != nil {
        c.JSON(http.StatusInternalServerError, gin.H{"error": "domain lookup failed"})
        return
    }
    if !ok {
        // open still recorded; domain not verified -> nothing claimable
        c.JSON(http.StatusOK, OpenPageResponse{OK: true, URL: url, Credited: false})
        return
    }

    // 4. credit the RESOLVED publisher (previously gated on body fields)
    if err := s.credits.RecordCredit(c.Request.Context(), publisher, u.Host, creditPerOpen); err != nil {
        c.JSON(http.StatusInternalServerError, gin.H{"error": "failed to record credit"})
        return
    }
    c.JSON(http.StatusOK, OpenPageResponse{OK: true, URL: url, Credited: true})
}
```

```go
// RecordCredit: idempotent upsert that accumulates the shadow balance
func (r *CreditRepo) RecordCredit(ctx context.Context, publisherID, domain string, amount int64) error {
    const q = `
        INSERT INTO publisher_credits (publisher_id, domain, shadow_credits, updated_at)
        VALUES ($1, $2, $3, now())
        ON CONFLICT (publisher_id, domain)
        DO UPDATE SET shadow_credits = publisher_credits.shadow_credits + EXCLUDED.shadow_credits,
                      updated_at = now()`
    _, err := r.db.ExecContext(ctx, q, publisherID, domain, amount)
    return err
}
```

**Defect 2 — `ClaimDomainCredits` `UPDATE ... RETURNING shadow_credits` returns the post-update value.** Setting `shadow_credits = 0` and returning the column yields `0`, so every claim pays out zero even when shadow credits accrued. Fix: a data-modifying CTE — a `snapshot` CTE with `FOR UPDATE` reads the **pre-update** value (and takes the row lock), the `zeroed` CTE zeroes it, and the outer query returns the snapshot amount. The whole statement is atomic; the row lock serializes concurrent claims.

```go
func (r *CreditRepo) ClaimDomainCredits(ctx context.Context, publisherID, domain string) (int64, error) {
    const q = `
        WITH snapshot AS (
            SELECT publisher_id, shadow_credits AS amount
            FROM publisher_credits
            WHERE publisher_id = $1 AND domain = $2
            FOR UPDATE
        ),
        zeroed AS (
            UPDATE publisher_credits
            SET shadow_credits = 0,
                updated_at = now()
            WHERE publisher_id = $1 AND domain = $2
            RETURNING publisher_id
        )
        SELECT s.amount
        FROM snapshot s
        JOIN zeroed z ON z.publisher_id = s.publisher_id`
    var claimed int64
    err := r.db.QueryRowContext(ctx, q, publisherID, domain).Scan(&claimed)
    if errors.Is(err, sql.ErrNoRows) {
        return 0, nil // nothing accrued
    }
    return claimed, err
}
```

The failure chain was **three silent failure modes stacking on one dead code path**. Full implementation: `/tmp/embed-fix/embeddings.ts`, verified by `/tmp/embed-fix/embeddings.test.ts` (18/18 passing, run with `node --experimental-strip-types --test`).

### 1. `createAutoProviders()` — return **ALL** healthy providers (was: first only)

A probe that passes is not proof an embed will succeed (LM Studio `/v1/models` 200s even when the embedding model is unloaded → `/v1/embeddings` 400s). Returning only the first healthy provider left nothing to fall back to.

```ts
export async function createAutoProviders(cfg: ProviderConfig): Promise<EmbedProvider[]> {
  const healthy: EmbedProvider[] = [];
  for (const Ctor of EMBEDDING_PROVIDERS) {
    const p = new Ctor(cfg);
    try {
      if (await p.healthy()) healthy.push(p);   // was: return [p];  (only first!)
    } catch { /* probe threw -> not healthy, keep probing */ }
  }
  return healthy;                                // ALL healthy -> recall can fall back
}
```

### 2. `recall()` — iterate with fallback on **embed failure AND empty vector**

`[]` is truthy in JS, so `if (result.vector)` accepted Ollama's 200-with-`embedding: []` for a missing model as a valid embed — recall silently returned nothing.

```ts
export async function recall(query, providers, store, k = 5) {
  let lastErr: unknown = new Error('no embedding providers available');
  for (const p of providers) {                       // iterate, don't stop at first
    try {
      const r = await p.embed(query);
      if (r.isError) throw new EmbedError(`${p.name}: ${r.error ?? 'embed error'}`);
      if (r.vector.length === 0)                     // explicit empty check, NOT truthiness
        throw new EmbedError(`${p.name} returned an empty vector`);
      return await store.search(r.vector, k);
    } catch (e) { lastErr = e; }                     // fall through to next provider
  }
  throw lastErr;                                     // never return silently-empty results
}
```

### 3. `wrapHandler()` — flag error results with `isError: true`

Error-shaped results (`{error: "model_not_loaded"}`) previously passed through unflagged, indistinguishable from success.

```ts
export function wrapHandler(fn: Handler): Handler {
  return async () => {
    const result = await fn();
    if (result && typeof result === 'object' && 'error' in result && result.error) {
      (result as { isError?: boolean }).isError = true;   // was: returned as-is
    }
    return result;
  };
}
```

### 4. `cosineSimilarity()` — throw on zero-length instead of returning NaN

```ts
export function cosineSimilarity(a: number[], b: number[]): number {
  if (a.length === 0) throw new EmbedError('cosineSimilarity: zero-length vector a');
  if (b.length === 0) throw new EmbedError('cosineSimilarity: zero-length vector b');
  if (a.length !== b.length) throw new EmbedError('cosineSimilarity: dimension mismatch');
  let dot = 0, na = 0, nb = 0;
  for (let i = 0; i < a.length; i++) { dot += a[i] * b[i]; na += a[i] * a[i]; nb += b[i] * b[i]; }
  const mag = Math.sqrt(na) * Math.sqrt(nb);
  if (mag === 0) throw new EmbedError('cosineSimilarity: zero-magnitude vector');
  return dot / mag;
}
```

