The schema/docs claimed `auto` fallback, but the hardcoded default `'lmstudio'` forced **explicit mode** (single provider, no fallback) for every user who didn't set the field — fixes 1–4 never engaged. Default fixed to `'auto'`; explicit modes intentionally stay single-provider.

```ts
export const configSchema = {
  provider: {
    type: 'string',
    enum: ['auto', 'lmstudio', 'ollama', 'openai'],
    default: 'auto',          // WAS: 'lmstudio' — the dead path
  },
} as const;

export function resolveProviders(cfg: ProviderConfig): ProviderMode[] {
  const mode: ProviderMode = cfg.provider ?? 'auto';
  if (mode === 'auto') return ['lmstudio', 'ollama'];  // expansion, fallback available
  return [mode];                                        // explicit = no fallback (by design)
}
