  if (s.dead) return 'boss-die';
  if (s.attacking) return 'boss-attack';
  if (s.flashElapsed === 0 && s.lastHitWasWeak) return 'boss-weak-hit';
  return 'boss-idle'; // ← default swallows row 8: weak-open never emitted
}
```

**After (fixed pure function).** The default branch now discriminates on `invulnerabilityTicks`: exposed state (`invulnerabilityTicks === 0`) holds `weakOpen`; `idle` is reserved for the i-frame recovery tail and normal play. `weakHit` fires only on the first flash tick (`flashElapsed === 0`):

```typescript
// src/render/sprite-layer.ts
export interface BossAnimState {
  readonly dead: boolean;
  readonly attacking: boolean;
  readonly weakPointExposed: boolean;
  readonly invulnerabilityTicks: number; // i-frame recovery tail countdown (>= 0)
  readonly flashElapsed: number;         // ticks since weak-hit flash began; 0 = first flash tick
  readonly lastHitWasWeak: boolean;
  readonly hp: number;
  readonly maxHp: number;
}

export const BOSS_ANIMS = {
  idle: 'boss-idle',
  weakOpen: 'boss-weak-open',
  weakHit: 'boss-weak-hit',
  attack: 'boss-attack',
  die: 'boss-die',
} as const;

// Spec 5.2 condition table (12 rows) mapped 1:1:
//   row 12 dead → die            (highest priority)
//   row 10 attacking → attack
//   row  6 weak hit first flash tick (flashElapsed === 0) → weakHit
//   row  8 weak point exposed (invulnerabilityTicks === 0) → weakOpen (hold)
//   rows 2/11 i-frame recovery tail or normal → idle
export function bossAnimationName(s: BossAnimState): string {
  if (s.dead) return BOSS_ANIMS.die;                                   // row 12
  if (s.attacking) return BOSS_ANIMS.attack;                           // row 10
  if (s.weakPointExposed && s.invulnerabilityTicks === 0) {            // rows 6/8 window
    if (s.flashElapsed === 0 && s.lastHitWasWeak) return BOSS_ANIMS.weakHit; // row 6
    return BOSS_ANIMS.weakOpen;                                        // row 8 — hold
  }
  return BOSS_ANIMS.idle;                                              // rows 2/11 — idle
}
```

Only the bottom three branches changed; the patch is a small, pure, branch-only edit (no state mutation, no I/O). The invariant is: **weakHit is a one-tick flash at `flashElapsed === 0`; every other tick of an open weak window is `weakOpen`; `idle` appears only when the weak window is closed** (`invulnerabilityTicks > 0` or window not exposed).

**Root cause:** `deleteNamespaceTool` in `src/mcp/tools/namespace.ts` only deleted `config.namespaceMappings[namespace]` and returned `success: true`. It never touched the filesystem, so `current.jsonl`, `manifest.json`, `.embeddings/`, and `.git/` all survived the "delete".

**Fix:** resolve the real directory from the recorded mapping → verify it stays inside the namespaces root (`path.resolve` + `path.relative`, blocks `../` and absolute escapes) → `fs.rmSync(dir, {recursive:true, force:true})` → only then unregister the mapping. The mapping unregister happens *after* the directory is gone, so an `fs` error never leaves a half-removed state. `force:true` swallows `ENOENT`, making deletion idempotent when the directory is already missing.

```ts
// src/mcp/tools/namespace.ts (fixed)
import fs from 'node:fs';
import path from 'node:path';
import { z } from 'zod';
import type { NamespaceConfig } from '../config'; // { namespacesRoot, defaultNamespace, activeNamespace, namespaceMappings }

const DeleteNamespaceArgs = {
  namespace: z.string().min(1),
  confirm: z.boolean(),
};

export function deleteNamespaceTool(config: NamespaceConfig, args: z.infer<typeof DeleteNamespaceArgs>) {
  const { namespace, confirm } = args;

  // --- existing guards preserved ---
  if (confirm !== true) {
    return { success: false, message: `Deletion requires confirm:true (got ${confirm})` };
  }
  if (namespace === config.defaultNamespace) {
    return { success: false, message: `Cannot delete default namespace "${namespace}"` };
  }
  if (namespace === config.activeNamespace) {
    return { success: false, message: `Cannot delete active namespace "${namespace}"` };
  }

  // --- resolve the REAL directory from the recorded mapping ---
  const mapped = config.namespaceMappings[namespace];
  if (mapped === undefined) {
    return { success: false, message: `Unknown namespace "${namespace}"` };
  }
  const targetDir = path.resolve(config.namespacesRoot, mapped);

  // --- guard: resolved path must stay inside the namespaces root ---
  const rel = path.relative(config.namespacesRoot, targetDir);
  if (rel === '' || rel.startsWith('..') || path.isAbsolute(rel)) {
    return { success: false, message: `Refusing to delete outside namespaces root: ${targetDir}` };
  }

  // --- delete data on disk FIRST ---
  // recursive:true removes current.jsonl, manifest.json, .embeddings/, .git/.
  // force:true is idempotent when the dir is already missing (ENOENT swallowed).
  // Any other fs error (EACCES/EPERM/…) throws here, so the mapping below is
  // never unregistered => no half-remove, config stays consistent with disk.
  fs.rmSync(targetDir, { recursive: true, force: true });

  // --- unregister the mapping ONLY after the directory is gone ---
  delete config.namespaceMappings[namespace];
  return { success: true, message: `Deleted namespace "${namespace}" (${targetDir})` };
}
```

Wiring (unchanged tool registration, same `delete_namespace` name):

```ts
server.registerTool('delete_namespace', DeleteNamespaceArgs, (args) => deleteNamespaceTool(config, args));
```

The order is load-bearing: **disk first, mapping second**. The traversal guard uses `path.relative` so `mapped: '../evil'` or an absolute path outside the root both fail; `rel === ''` also rejects a mapping that points at the root itself.

