cd "$(dirname "$0")/../.."
go run ./scripts/generate-openapi "$@"
```

### Fix 2 — Generator regex must resolve `Str*` constants

The route scanner matches `r.Group(...)`, `r.GET(...)`, etc. A regex that only accepts string literals (`r\.Group\("..."`) silently drops registrations written with constants (`v1 := r.Group(StrV1X)`, `r.GET(StrSystem+"/ping")`) — the generated spec loses whole route trees and Spec Validation goes red.

The fix adds `loadStringConstants` (parses `const X = "..."`, `const X string = "..."`, and grouped `const ( ... )` blocks across the app tree) and resolves identifiers — bare and package-qualified (`consts.StrV1X`) — inside path expressions:

```go
// constLineRe:  const Name [string] = "value"
var constLineRe = regexp.MustCompile(`\bconst\s+([A-Za-z_][A-Za-z0-9_]*)\s*(?:string)?\s*=\s*"([^"]*)"`)
// constBlockRe: const ( ... )
var constBlockRe = regexp.MustCompile(`(?m)\bconst\s*\(([^)]*)\)`)

func loadStringConstants(dirs ...string) map[string]string {
	consts := map[string]string{}
	for _, dir := range dirs {
		_ = filepath.WalkDir(dir, func(path string, d fs.DirEntry, err error) error {
			if err != nil || d.IsDir() || !strings.HasSuffix(path, ".go") ||
				strings.HasSuffix(path, "_test.go") {
				return nil
			}
			src, _ := os.ReadFile(path)
			text := string(src)
			for _, m := range constBlockRe.FindAllStringSubmatch(text, -1) { // grouped first
				for _, e := range constEntryRe.FindAllStringSubmatch(m[1], -1) {
					consts[e[1]] = e[2]
				}
			}
			rest := constBlockRe.ReplaceAllString(text, "") // single-line outside blocks
			for _, m := range constLineRe.FindAllStringSubmatch(rest, -1) {
				consts[m[1]] = m[2]
			}
			return nil
		})
	}
	return consts
}

// resolveIdentifier: bare (StrV1X) or package-qualified (consts.StrV1X).
func resolveIdentifier(tok string, consts map[string]string) (string, bool) {
	if v, ok := consts[tok]; ok {
		return v, true
	}
	if i := strings.LastIndexByte(tok, '.'); i >= 0 {
		if v, ok := consts[tok[i+1:]]; ok {
			return v, true
		}
	}
	return "", false
}

// extractPath: "literal" | StrV1X | consts.StrV1X | StrSystem + "/ping"
// Unresolvable identifiers yield ok=false → the route is dropped with a
// verbose warning instead of being emitted with a wrong path.
func extractPath(expr string, consts map[string]string, resolve bool) (string, bool) {
	var b strings.Builder
	for _, part := range splitConcat(strings.TrimSpace(expr)) { // top-level '+'
		part = strings.TrimSpace(part)
		if part == "" {
			continue
		}
		if len(part) >= 2 && (part[0] == '"' || part[0] == '\'') {
			b.WriteString(part[1 : len(part)-1])
			continue
		}
		if !resolve {
			return "", false // pre-fix regex behavior
		}
		if v, ok := resolveIdentifier(part, consts); ok {
			b.WriteString(v)
			continue
		}
		return "", false
	}
	return b.String(), true
}
```

`collectRoutes` then (1) resolves group prefixes first — `v1 := r.Group(consts.StrV1X)` registers `v1 → "/v1x"` — and (2) prefixes every `v1.GET("/users")` with its group. Comments are stripped before matching so commented-out examples never leak into the spec.

