**2. Test — two independent contexts, unique tree, `expect.poll` propagation** (`tests/integration/realtime-sync.spec.ts`)

```ts
import { expect, test } from '@playwright/test';
import { randomUUID } from 'node:crypto';
import { createUniqueTree } from './helpers/api';

test.describe('realtime sync (SSE + Yjs)', () => {
  test('node created in context A propagates to context B', async ({ browser }) => {
    // (1) ONE newContext() per client: independent storage + EventSource connections.
    //     Two pages in one context share a storage partition and connection bookkeeping
    //     => false-pass (shared in-context store) or false-fail (second page steals
    //     the first's EventSource slot).
    const ctxA = await browser.newContext();
    const ctxB = await browser.newContext();
    const pageA = await ctxA.newPage();
    const pageB = await ctxB.newPage();

    // (2) Fresh uniquely-named tree through page.request (Vite origin) so the
    //     injected dev JWT authenticates; a raw :8092 call would 401.
    const tree = await createUniqueTree(pageA);
    const nodeLabel = `sync-node-${randomUUID().slice(0, 8)}`;

    await pageA.goto(`/tree/${tree.id}`);
    await pageB.goto(`/tree/${tree.id}`);
    await expect(pageA.locator('.react-flow')).toBeVisible();
    await expect(pageB.locator('.react-flow')).toBeVisible();

    // Create a node in context A via the UI (dblclick canvas -> name -> Enter)
    await pageA.locator('.react-flow__pane').dblclick({ position: { x: 120, y: 120 } });
    await pageA.locator('.node-create-input').fill(nodeLabel);
    await pageA.keyboard.press('Enter');

    // (3) Deterministic: poll, never sleep. 20s budget covers suite contention.
    await expect
      .poll(
        async () => pageB.locator('.react-flow__node', { hasText: nodeLabel }).count(),
        { timeout: 20_000, intervals: [250, 500, 1_000, 2_000] },
      )
      .toBeGreaterThan(0);

    // Exact label, not stale/partial text
    await expect(pageB.locator('.react-flow__node', { hasText: nodeLabel })).toContainText(nodeLabel);

    await ctxB.close();
    await ctxA.close();
  });
});
```

**3. Helper — authenticated tree creation through the Vite proxy** (`tests/integration/helpers/api.ts`)

```ts
export async function createUniqueTree(page: Page, prefix = 'sync-e2e') {
  const name = `${prefix}-${Date.now()}-${randomUUID().slice(0, 8)}`;
  const res = await page.request.post('/api/trees', { data: { name } });
  if (!res.ok()) throw new Error(`createUniqueTree failed: ${res.status()} ${await res.text()}`);
  const { tree } = await res.json();
  if (!tree?.id) throw new Error(`no tree id: ${JSON.stringify(await res.json())}`);
  return tree;
}
```

