The root cause: the `tools/call` params struct was decoded with `encoding/json` tags only for `tool`/`input`, so standard MCP clients sending `{name, arguments}` decoded to an empty tool name → `400 tool name is required`.

The fix is a dual-shape `ToolCallParams` with a custom `UnmarshalJSON` that decodes **both** shapes in one pass, prefers `name`/`arguments` whenever either is present, falls back to `tool`/`input`, and returns `ErrToolNameRequired` only when both pairs are absent (including `null`/missing params):

```go
// mcp/params.go
var ErrToolNameRequired = errors.New("tool name is required")

type ToolCallParams struct {
	Name      string          `json:"name"`
	Arguments json.RawMessage `json:"arguments,omitempty"`
}

// UnmarshalJSON accepts both shapes; standard (name, arguments) wins,
// legacy (tool, input) is the fallback, error only when both are absent.
func (p *ToolCallParams) UnmarshalJSON(data []byte) error {
	var wire struct {
		Name      string          `json:"name"`
		Arguments json.RawMessage `json:"arguments"`
		Tool      string          `json:"tool"`
		Input     json.RawMessage `json:"input"`
	}
	if err := json.Unmarshal(data, &wire); err != nil {
		return fmt.Errorf("decode tools/call params: %w", err)
	}
	if bytes.Equal(bytes.TrimSpace(data), []byte("null")) {
		return ErrToolNameRequired
	}
	*p = ToolCallParams{}
	switch {
	case wire.Name != "" || wire.Arguments != nil:
		p.Name, p.Arguments = wire.Name, wire.Arguments // standard — preferred
	case wire.Tool != "" || wire.Input != nil:
		p.Name, p.Arguments = wire.Tool, wire.Input     // legacy — fallback
	default:
		return ErrToolNameRequired
	}
	return nil
}
```

The handler surfaces it as a JSON-RPC invalid-params error (`-32602`, message `"tool name is required"`), and the HTTP layer maps that to HTTP 400:

```go
// mcp/handler.go — Handle() excerpt
if err := json.Unmarshal(body, &req); err != nil {
	code := CodeParseError
	var syn *json.SyntaxError
	if !errors.As(err, &syn) {
		code = CodeInvalidParams
	}
	if errors.Is(err, ErrToolNameRequired) {
		code = CodeInvalidParams
		msg = ErrToolNameRequired.Error() // "tool name is required"
	}
	return Response{JSONRPC: "2.0", Error: &RPCError{Code: code, Message: msg}}
}
// HandleCall rejects an empty resolved name as defense-in-depth:
if params.Name == "" { return nil, ErrToolNameRequired }
```

Table tests in `mcp/params_test.go` (`TestToolCallParamsUnmarshal`, `TestStandardAndLegacyShapesResolveIdentically`) assert both shapes decode identically and re-encode to the same canonical output; `handler_test.go` and `cmd/server/main_test.go` cover the full JSON-RPC/HTTP path.

**Root cause.** The legacy engine's cost tracker read a top-level `totalTokens` field that never existed on the tracker record. The actual usage object is nested under `estimatedCost.tokens.totalTokens`. Reading the missing field yields `undefined`; `Number(undefined)` → `NaN`, and every downstream aggregation (`avgTokens = totalTokens / games`, `avgCost`, `avgLatency`) silently coerced `NaN` to `0` — so all 621 benchmark games reported `0` tokens/cost/latency despite "cost tracking" being advertised.

The fix has three parts.

**1. Read the nested field in the tracker.**

```ts
// legacy engine, before
const totalTokens = Number(result.totalTokens);        // undefined -> NaN -> 0
const cost = Number(result.totalCostUSD);

// after — nested shape from APITracker
const est = result.estimatedCost ?? {};
const tokens = est.tokens ?? {};
const totalTokens =
  finite(tokens.totalTokens) ??
  finite(tokens.promptTokens) + finite(tokens.completionTokens); // streaming fallback
const cost = finite(est.costInUSD?.total) ?? 0;
const latency = finite(result.latencyInSeconds ?? est.latencyInSeconds) ?? 0;

function finite(v: unknown): number | undefined {
  const n = Number(v);
  return Number.isFinite(n) ? n : undefined;
}
```

**2. Extract usage collection into a testable `legacy-usage-collector.js`** (pure functions over APITracker records — no DB, no globals):

```js
'use strict';
// legacy-usage-collector.js

const safe = (v, fallback = 0) => {
  const n = Number(v);
  return Number.isFinite(n) ? n : fallback;
};
const modelOf = (r) => String((r && r.model) || 'unknown').trim();

/** Pull the real values out of one APITracker record. */
function extractUsage(record) {
  const est = (record && record.estimatedCost) || {};
  const tokens = est.tokens || {};
  const promptTokens = safe(tokens.promptTokens);
  const completionTokens = safe(tokens.completionTokens);
  return {
    model: modelOf(record),
    promptTokens,
    completionTokens,
    totalTokens: safe(tokens.totalTokens, promptTokens + completionTokens),
    cost: safe(est.costInUSD && est.costInUSD.total),
    latencyInSeconds: safe(record.latencyInSeconds || est.latencyInSeconds),
  };
}

/** Aggregate token/cost counts across tracker records, per model. */
function collectUsage(records) {
  const byModel = new Map();
  for (const rec of records || []) {
    const u = extractUsage(rec);
    if (!byModel.has(u.model)) {
      byModel.set(u.model, { model: u.model, games: 0, totalTokens: 0, cost: 0, latencySum: 0 });
    }
    const a = byModel.get(u.model);
    a.games += 1;
    a.totalTokens += u.totalTokens;
    a.cost += u.cost;
    a.latencySum += u.latencyInSeconds;
  }
  return [...byModel.values()].map((a) => ({
    model: a.model,
    games: a.games,
    totalTokens: a.totalTokens,
    avgTokens: a.games ? a.totalTokens / a.games : 0,
    avgCost: a.games ? a.cost / a.games : 0,
    avgLatency: a.games ? a.latencySum / a.games : 0,
  }));
}

/** Per-model average latency in seconds (for stats-collector). */
function collectLatencyByModel(records) {
  const acc = new Map();
  for (const rec of records || []) {
    const u = extractUsage(rec);
    if (!acc.has(u.model)) acc.set(u.model, []);
    acc.get(u.model).push(u.latencyInSeconds);
  }
  const out = {};
  for (const [model, list] of acc) out[model] = list.reduce((x, y) => x + y, 0) / list.length;
  return out;
}

module.exports = { extractUsage, collectUsage, collectLatencyByModel };
```

**3. Fill `stats-collector/models.ts` + `repository.ts` from real DB rows** instead of hardcoded zeros:

```ts
// stats-collector/models.ts
export interface ModelStats {
  model: string;
  games: number;
  totalTokens: number;
  avgTokens: number;
  avgCost: number;
  avgLatency: number;
}

export interface UsageRow {
  model: string;
  games: number;
  total_tokens: number;   // prompt + completion
  cost_usd: number;
  avg_latency_s: number;
}

export function modelStatsFromRows(rows: UsageRow[]): ModelStats[] {
  return rows.map((r) => ({
    model: r.model,
    games: r.games,
    totalTokens: r.total_tokens,
    avgTokens: r.games > 0 ? r.total_tokens / r.games : 0,
    avgCost: r.games > 0 ? r.cost_usd / r.games : 0,
    avgLatency: r.avg_latency_s,
  }));
}
```

```ts
// stats-collector/repository.ts
// Before: SELECT ... returned literal 0 rows/zeros for token/cost columns.
export async function getModelUsage(runId: string): Promise<ModelStats[]> {
  const { rows } = await pool.query(
    `SELECT
        COALESCE(model, 'unknown')                              AS model,
        COUNT(*)                                                AS games,
        COALESCE(SUM(COALESCE(prompt_tokens,0) + COALESCE(completion_tokens,0)), 0) AS total_tokens,
        COALESCE(SUM(COALESCE(cost_usd,0)), 0)                  AS cost_usd,
        COALESCE(AVG(COALESCE(latency_ms,0)) / 1000.0, 0)       AS avg_latency_s
     FROM api_calls
     WHERE benchmark_run_id = $1
     GROUP BY model`,
    [runId],
  );
  return modelStatsFromRows(rows);
}
```

`token_usage` and `api_calls` rows are joined/coalesced so `NULL`s and missing columns never propagate `NaN` into the report; the collector above is the single source of truth for tracker-shaped data, and the repository is the single source for DB-shaped data.

**Root cause:** the chi router mounted the SPA fallback `r.Get("/*")` with no `/docs` routes, so every `/docs*` request fell through to the catch-all and returned `index.html` (or 404) — the spec was never reachable.

**Fix:** a `DocsHandler` registered **before** the SPA fallback, plus a spec-resolution ladder mirroring `resolveDistDir`. Key code from `openapi.go`:

```go
// Register mounts the docs routes. MUST be called before the SPA
// catch-all, otherwise r.Get("/*") swallows /docs.
func (h *DocsHandler) Register(r chi.Router) {
    r.Get("/docs", h.ScalarPage)
    r.Get("/docs/openapi.yaml", h.RawSpec)
    r.Get("/docs/*", h.Subpath)
}

// ScalarPage renders the Scalar viewer (CDN) pointed at the local spec.
func (h *DocsHandler) ScalarPage(w http.ResponseWriter, r *http.Request) {
    w.Header().Set("Content-Type", "text/html; charset=utf-8")
    w.WriteHeader(http.StatusOK)
    io.WriteString(w, docsHTML) // <script id="api-reference" data-url="/docs/openapi.yaml">
                                // <script src="https://cdn.jsdelivr.net/npm/@scalar/api-reference"></script>
}

// RawSpec streams the spec verbatim; path resolved per request.
func (h *DocsHandler) RawSpec(w http.ResponseWriter, r *http.Request) {
    specPath, ok := resolveSpecPath()
    if !ok {
        writeJSON(w, http.StatusNotFound, map[string]string{"error": "openapi spec not found"})
        return
    }
    data, err := os.ReadFile(specPath)
    if err != nil { writeJSON(w, http.StatusInternalServerError, ...); return }
    w.Header().Set("Content-Type", "application/yaml; charset=utf-8")
    w.Write(data)
}

// Subpath: /docs/ → 301 /docs; anything else → JSON 404.
func (h *DocsHandler) Subpath(w http.ResponseWriter, r *http.Request) {
    switch rest := chi.URLParam(r, "*"); rest {
    case "/", "":
        http.Redirect(w, r, "/docs", http.StatusMovedPermanently)
    default:
        writeJSON(w, http.StatusNotFound, map[string]string{"error": "not found", "path": r.URL.Path})
    }
}

// Spec resolution: ASCE_API_SPEC env override, then a CWD-candidate
// ladder — the exact pattern resolveDistDir uses for the SPA dist dir.
func resolveSpecPath() (string, bool) {
    if p := os.Getenv("ASCE_API_SPEC"); p != "" {
        if info, err := os.Stat(p); err == nil && !info.IsDir() {
            abs, _ := filepath.Abs(p)
            return abs, true
        }
        return p, false
    }
    for _, c := range []string{"api/openapi.yaml", "./api/openapi.yaml",
        "../api/openapi.yaml", "../../api/openapi.yaml"} {
        if info, err := os.Stat(c); err == nil && !info.IsDir() {
            abs, _ := filepath.Abs(c)
            return abs, true
        }
    }
    return "api/openapi.yaml", false
}
```

Router wiring in `main.go` — ordering is the whole fix:

```go
func NewRouter() chi.Router {
    r := chi.NewRouter()
    NewDocsHandler().Register(r)          // /docs, /docs/openapi.yaml, /docs/*
    if distDir, ok := resolveDistDir(); ok {
        r.Get("/*", spaHandler(distDir).ServeHTTP)   // SPA fallback, AFTER docs
    } else {
        r.Get("/*", http.NotFoundHandler().ServeHTTP)
    }
    return r
}
```

