func CheckWebhookEntries(raw []byte, hookBase string) []error {
	var entries []json.RawMessage
	if err := json.Unmarshal(raw, &entries); err != nil {
		return []error{fmt.Errorf("GET /api/flows is not a JSON array: %w", err)}
	}
	if hookBase == "" {
		hookBase = defaultHookBase // http://localhost:9876
	}
	var errs []error
	for i, e := range entries {
		var m map[string]json.RawMessage
		if err := json.Unmarshal(e, &m); err != nil {
			errs = append(errs, fmt.Errorf("entry[%d]: not a JSON object: %w", i, err))
			continue
		}
		name, webhook := stringField(m, "name"), boolField(m, "webhook")
		rawURL, hasURL := m["webhook_url"]
		if !webhook {
			if hasURL {
