		want := hookBase + "/hooks/" + name
		if !hasURL { /* ...error "missing" */ }
		var got string
		if err := json.Unmarshal(rawURL, &got); err != nil { /* ...not a string */ }
		if got != want { /* ...mismatch, want = hookBase + "/hooks/" + name */ }
	}
	return errs
}
