**Root cause.** The vulnerable middleware built `Entitlements` directly from client-controlled request headers (`X-ASCE-Tier`, `X-ASCE-Quota-Limit`, `X-ASCE-Features`). Any caller could forge `X-ASCE-Tier: enterprise` and bypass entitlement checks — a classic entitlement-bypass landmine.

**The fix** (repo: `/home/kara/entitlements`, module `entitlements`):
1. Delete every `r.Header.Get("X-ASCE-*")` read.
2. Derive identity server-side from `auth.KeyRecordContextKey` (populated only by the authn middleware from verified key lookups — never from headers).
3. Derive tier server-side via `tiers.Service.GetAccountTier(apiKeyID)`, falling back to `tiers.Free()` when the key is **unassigned** (`(*Tier, nil)`) or the **db is nil** (`(nil, error)`).
4. Static regression tripwire test forbids any `Header.Get("X-ASCE` / `Header["X-ASCE` from reappearing.

**Before (vulnerable, deleted):**
```go
func EntitlementsFromHeaders(next http.Handler) http.Handler {
    return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
        limit, _ := strconv.ParseInt(r.Header.Get("X-ASCE-Quota-Limit"), 10, 64)
        e := Entitlements{
            TierName:   r.Header.Get("X-ASCE-Tier"),      // ← client-controlled!
            QuotaLimit: limit,                            // ← client-controlled!
            Features:   strings.Split(r.Header.Get("X-ASCE-Features"), ","),
        }
        next.ServeHTTP(w, r.WithContext(context.WithValue(r.Context(), entitlementsCtxKey, e)))
    })
}
```

**After (fixed — `middleware/entitlements.go`):**
```go
func EntitlementsFromKeyRecord(svc *tiers.Service) func(http.Handler) http.Handler {
    return func(next http.Handler) http.Handler {
        return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
            e := resolve(r.Context(), svc) // r's headers are never consulted
            ctx := context.WithValue(r.Context(), entitlementsCtxKey, e)
            next.ServeHTTP(w, r.WithContext(ctx))
        })
    }
}

func resolve(ctx context.Context, svc *tiers.Service) Entitlements {
    rec, ok := auth.KeyRecordFromContext(ctx) // identity: server-side only
    if !ok {
        return fromTier(tiers.Free()) // unauthenticated caller
    }
    t, err := svc.GetAccountTier(rec.APIKeyID) // tier: server-side only
    if err != nil || t == nil {
        return fromTier(tiers.Free()) // unassigned or DB nil → free
    }
    return fromTier(*t)
}
```

Supporting pieces: `auth.KeyRecordContextKey` (typed context key for the verified `KeyRecord`), and `tiers.Service.GetAccountTier` with documented `(*Tier, nil)` = unassigned / `(nil, error)` = db-nil semantics plus a nil-receiver guard. The old middleware is retained only as `entitlements_legacy.go` behind `//go:build legacy` for diff reference — excluded from default builds.

**Root cause (BUG-004):** `guard_manager._check_tests` unconditionally early-returned `PASS` with `"No files staged — skipped"` on clean trees, so chained suites (totalstack ACM parity) never executed on idle audits. Vacuous greens hid BUG-004 for ~2 days.

**Fix:** a `test_on_clean` config flag (default `False`) on `GuardConfig`. When `True`, a clean-tree guard runs the full `test_command` — diff-mode `_discover` returns `None` and control **falls through** to the full-suite path instead of the vacuous skip. Default `False` preserves legacy skip semantics for callers that opt out.

Files: `gitreins_guard/guard_manager.py`, `tests/test_guard_manager.py` (10 unit tests, all passing).

```python
@dataclass
class GuardConfig:
    test_command: str = "pytest -q"
    test_on_clean: bool = False   # <-- the fix: run full suite on clean trees
    diff_mode: bool = True
    timeout: float = 600.0

class GuardManager:
    def _discover(self) -> Optional[List[str]]:
        """Non-empty list of changed files, or None when nothing discovered.
        Full mode (diff_mode=False) always returns None."""
        if not self.config.diff_mode:
            return None
        files = self.git.staged_files()
        return list(files) if files else None

    def _check_tests(self, suite: Optional[Suite] = None) -> GuardResult:
        """Tests step. Clean-tree semantics:
        * diff-mode + _discover() -> None + test_on_clean=False
            -> vacuous PASS, "No files staged — skipped"   (legacy, the bug)
        * diff-mode + _discover() -> None + test_on_clean=True
            -> FULL FALLTHROUGH: suite command runs
        * diff-mode + changed files / full mode -> suite always runs"""
        if self.config.diff_mode and self._discover() is None:
            if not self.config.test_on_clean:
                self.log(f"clean tree: skipping tests — {NO_FILES_STAGED}")
                return GuardResult.passed(NO_FILES_STAGED)
            self.log("clean tree: test_on_clean=True — falling through to full suite")
        command = suite.command if suite is not None else self.config.test_command
        try:
            proc = self.runner.run(command, self.config.timeout)
        except subprocess.TimeoutExpired:
            return GuardResult.failed(f"tests timed out after {self.config.timeout}s: {command}")
        if proc.returncode == 0:
            return GuardResult.passed(f"tests passed: {command}")
        return GuardResult.failed(f"tests failed (exit {proc.returncode}): {command}")
```

The `Guard` chain runner (5-suite totalstack, 4-suite parity) calls `_check_tests` per suite with fail-fast, so a `test_on_clean=True` idle audit executes every chained suite.

**Root cause (GAP-019 / tick 106):** The DELETE handler for `DELETE /v1/sessions/{id}` called `store.delete()` unconditionally and returned `200 OK` even when the id wasn't a tracked session, while `GET /v1/sessions/{id}` and `POST /v1/sessions/{id}/cancel` both returned `404`. The three verbs validated session existence through different code paths, so behavior drifted.

**The fix:** Route all three verbs through one shared existence gate — a `require_tracked_session` dependency that resolves the session (or raises `404`) before the handler runs. DELETE now 404s unknown tracked sessions instead of silently succeeding.

**Before (buggy):**
```python
@router.delete("/v1/sessions/{session_id}", response_model=DeleteOut)
def delete_session(session_id: str) -> DeleteOut:
    store.delete(session_id)          # BUG: no existence check — unknown ids return 200
    return DeleteOut(status="deleted")
```

**After (fixed, tick 106):**
```python
from fastapi import APIRouter, Depends, HTTPException

def require_tracked_session(session_id: str) -> Session:
    """Shared existence gate — single source of truth for session validation."""
    session = store.get(session_id)
    if session is None:
        raise HTTPException(status_code=404, detail=f"session '{session_id}' not found")
    return session

@router.get("/v1/sessions/{session_id}", response_model=SessionOut)
def get_session(session: Session = Depends(require_tracked_session)) -> SessionOut:
    return SessionOut(id=session.id, state=session.state)

@router.post("/v1/sessions/{session_id}/cancel", response_model=SessionOut)
def cancel_session(session: Session = Depends(require_tracked_session)) -> SessionOut:
    store.cancel(session.id)
    return SessionOut(id=session.id, state="cancelled")

@router.delete("/v1/sessions/{session_id}", response_model=DeleteOut)
def delete_session(session: Session = Depends(require_tracked_session)) -> DeleteOut:
    # Fix: existence validated above; unknown ids never reach the handler.
    store.delete(session.id)
    return DeleteOut(status="deleted")
```

