**Root cause (GAP-016):** `POST /v1/loops` was documented in the README but never registered in the router (loops are declarative via `.ralph.yaml`). The only `NoRoute` handler was registered *inside* the frontend branch, so it ran only when the `dist` directory existed. In API-only mode (no dist), gin fell back to its plain-text `404 page not found` — wrong format for API clients, and no guidance about `.ralph.yaml`.

**Fix:** extract a `writeAPINotFound` JSON handler and register `r.NoRoute` in **both** modes. Frontend-present mode routes `/v1/*` misses to it and serves the SPA for everything else; API-only mode registers it directly.

```go
// writeAPINotFound is the JSON NoRoute handler registered in BOTH modes.
// Unknown routes always get application/json (never gin's text 404), and
// the phantom POST /v1/loops gets a targeted .ralph.yaml hint.
func writeAPINotFound(c *gin.Context) {
	if c.Request.Method == http.MethodPost && c.Request.URL.Path == "/v1/loops" {
		c.JSON(http.StatusNotFound, gin.H{
			"error":   "route not found",
			"message": "POST /v1/loops is not a supported API endpoint. Loops are declarative: define them in .ralph.yaml instead.",
			"hint":    "See README: loops are declared in .ralph.yaml, not created via the API.",
		})
		return
	}
	c.JSON(http.StatusNotFound, gin.H{
		"error":   "route not found",
		"message": "the requested resource does not exist",
	})
}

func setupRouter(cfg Config) *gin.Engine {
	r := gin.New()

	v1 := r.Group("/v1")
	v1.GET("/loops", listLoops) // POST /v1/loops intentionally NOT registered
	v1.GET("/health", health)

	if cfg.FrontendDist != "" {
		r.Static("/assets", cfg.FrontendDist+"/assets")
		r.NoRoute(func(c *gin.Context) {
			if strings.HasPrefix(c.Request.URL.Path, "/v1/") {
				writeAPINotFound(c) // API miss → JSON, never the SPA shell
				return
			}
			serveIndexHTML(c) // non-API path → SPA fallback
		})
	} else {
		r.NoRoute(writeAPINotFound) // API-only: JSON 404 instead of text 404
	}
	return r
}
```

