And stop masking FK violations as outages in the API:

```ts
// server/src/routes/trees.ts
import { DatabaseError } from 'pg';

try {
  await tx`insert into tree_members (tree_id, user_id, role)
           values (${treeId}, ${userId}, 'owner')`;
} catch (err) {
  if (err instanceof DatabaseError && err.code === '23503') {
    return res.status(422).json({ error: 'unknown_user', detail: err.detail }); // not 503
  }
  if (err instanceof DatabaseError && /ECONNREFUSED|connection|timeout/i.test(err.message)) {
    return res.status(503).json({ error: 'database_unavailable' });
  }
  throw err;
}
