DF-014 — contract-id alias resolution stays strict, so a mistyped flag can never be reinterpreted as an alias:

```go
func (r *AliasRegistry) ResolveContractID(raw string) (string, error) {
    if raw == "" { return "", errors.New("missing contract id") }
    if strings.HasPrefix(raw, "-") {
        return "", fmt.Errorf("invalid contract id %q: identifiers may not begin with '-' (check for a mistyped flag name)", raw)
    }
    if canonical, ok := r.aliases[raw]; ok { return canonical, nil } // "main" → 0x1f2e…
    hexID := strings.TrimPrefix(raw, "0x")
    if hexID != "" && isHex(hexID) { return raw, nil }
    return "", fmt.Errorf("invalid contract id %q: not a raw hex id and no such alias", raw)
}

// Run ties it together: subcommand dispatch → whitelist parse → alias resolve.
func Run(reg *AliasRegistry, argv []string) (string, map[string]string, error) {
    sub := Lookup(argv[0])                       // unknown subcommand errors
    vals, pos, err := ParseArgs(sub, argv[1:])   // unknown flag errors HERE, first
    if err != nil { return "", nil, err }
    if len(pos) == 0  { return "", nil, fmt.Errorf("subcommand %q requires a contract id", sub.Name) }
    if len(pos) > 1   { return "", nil, fmt.Errorf("subcommand %q accepts exactly one contract id, got %d", sub.Name, len(pos)) }
    return reg.ResolveContractID(pos[0])         // …before the alias layer runs (DF-014)
}
```

