err := runWithTimeout(t, "performHealthCheck", func() error {
	cm.mu.Lock()
	cm.mu.Unlock() // FIX: release cm.mu BEFORE the lock-taking call
	return cm.performHealthCheck()
})
```

```go
// runWithTimeout bounds every probe: a regression re-hangs at most
// deadlockProbeTimeout (3s) instead of "full suite duration".
func runWithTimeout(t *testing.T, name string, fn func() error) error {
	done := make(chan error, 1)
	go func() { done <- fn() }()
	select {
	case err := <-done:
		return err
	case <-time.After(deadlockProbeTimeout):
		return fmt.Errorf("%s did not return within %v — self-deadlock (lock held across a lock-taking call)", name, deadlockProbeTimeout)
	}
}
```

